<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<!-- Original atlas: generated with the managed Codex built-in GPT Image tool on 2026-11-20; latest available GPT Image model requested. Nine generated tiles are embedded once as WebP and cropped by the game. Prompt: Create one square image atlas for a charming woodland bookmark finding game. EXACT 3 by 3 grid of nine equal square illustrations with no gutters, no text, no letters, no numbers. Read left to right, top to bottom: 1 a brass telescope looking at a crescent moon on navy; 2 a red vintage toy car on golden ochre; 3 a steaming teacup beside an open book on sage green; 4 a mossy stone bridge over a creek on turquoise; 5 a small orange fox holding a folded map on warm ivory; 6 a violin with a bow on terracotta; 7 a red mushroom beneath ferns on dark pine green; 8 a tiny blue sailboat on pale blue water; 9 a yellow paper lantern hanging in a cedar tree at dusk. Consistent mid-century childrens nature encyclopedia illustration, gouache with visible brush texture, clean silhouettes, tightly art directed earthy colours, each object centered safely inside its own tile. Full bleed flat artwork, no surrounding mockup, no typography. -->
<meta name="theme-color" content="#244638">
<title>Bookmark Burrow</title>
<style>
@font-face{font-family:Burrow;src:url(data:font/ttf;base64,) format("truetype");font-display:swap}
:root{--pine:#244638;--cream:#faf1dc;--ink:#223d31;--rust:#9b3826;--gold:#e8bf65;--atlas:url("data:image/webp;base64,")}
*{box-sizing:border-box}body{margin:0;background:var(--pine);color:var(--cream);font:17px/1.5 system-ui,sans-serif;scrollbar-color:var(--gold) var(--pine)}
::selection{background:var(--gold);color:var(--ink)}a{color:inherit;text-underline-offset:4px}button,input{font:inherit}button{cursor:pointer;touch-action:manipulation}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid var(--gold);outline-offset:4px}button:disabled{cursor:default;opacity:.6}header{max-width:1180px;margin:auto;padding:26px 30px 18px;display:flex;justify-content:space-between;align-items:center;gap:15px}header a{font-size:14px;min-height:44px;display:flex;align-items:center}header span{font-size:14px;color:#ead9b5}
main{max-width:1180px;margin:auto;padding:0 30px 40px}.masthead{display:flex;gap:30px;align-items:end;margin:8px 0 27px}.masthead h1{font:clamp(38px,5.8vw,72px)/1.06 Burrow,serif;letter-spacing:-.025em;max-width:650px;margin:0}.masthead p{max-width:310px;margin:0;color:#ecdfc5;font-size:16px}.work{display:grid;grid-template-columns:290px 1fr;gap:35px;align-items:start}
.request{background:var(--cream);color:var(--ink);padding:27px 24px;position:sticky;top:20px;box-shadow:0 9px 25px #10281d55;transform:rotate(-1deg)}.request h2{font:27px/1.2 Burrow,serif;margin:15px 0}.request p{margin:12px 0}.count{font-size:14px;font-weight:700;font-variant-numeric:tabular-nums;display:flex;justify-content:space-between;border-bottom:1px solid #b9b59f;padding-bottom:13px}.clue{font-size:19px;min-height:116px}.signed{font:19px Burrow,serif;color:var(--rust)}.primary{background:var(--pine);color:var(--cream);border:0;padding:12px 18px;border-radius:5px;width:100%;font-weight:650;margin-top:12px;min-height:48px}.primary:hover:not(:disabled){background:#356149}.plain{border:0;background:transparent;text-decoration:underline;text-underline-offset:4px;color:var(--ink);padding:12px 0;min-height:44px}.request :focus-visible{outline-color:var(--rust)}#feedback{font-size:15px;min-height:48px}#hintText{font-size:15px;color:#62412b}#next{background:var(--rust)}[hidden]{display:none!important}
.archive{min-width:0}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:15px;flex-wrap:wrap}.toolbar h2{font:24px Burrow,serif;margin:0}.switch{border:1px solid #c9d5be;background:transparent;border-radius:5px;color:var(--cream);min-height:44px;padding:8px 12px}.switch[aria-pressed=true]{background:var(--gold);color:var(--ink);border-color:var(--gold)}.search{display:block;margin-bottom:18px}.search span{font-size:14px;display:block;margin-bottom:6px}.search input{width:100%;min-height:46px;background:#f9f1dd;color:var(--ink);border:0;border-radius:4px;padding:10px 13px;caret-color:var(--rust)}input::placeholder{color:#56624e}
.board{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;align-items:start}.bookmark{border:0;border-radius:2px;background:var(--cream);color:var(--ink);text-align:left;padding:7px 7px 11px;box-shadow:0 5px 13px #0e251c44;width:100%;position:relative;transition:transform .22s cubic-bezier(.16,1,.3,1)}.bookmark:hover{transform:translateY(-4px)}.bookmark[aria-pressed=true]{outline:4px solid var(--gold);outline-offset:3px;transform:translateY(-4px)}.picture{display:block;width:100%;aspect-ratio:1;background-image:var(--atlas);background-size:300% 300%;background-position:var(--x) var(--y)}.label{display:block;padding:9px 5px 3px;font:17px/1.2 Burrow,serif}.tags{display:block;padding:4px 5px 0;font-size:12px;line-height:1.5;color:#4a5a43}.text-only .picture{display:none}.text-only .bookmark{min-height:120px;padding:15px 10px}.text-only .label{font-size:20px}#empty{padding:25px 0;color:var(--cream)}.caption{font-size:13px;color:#ead9b5;margin:18px 0}.finish{background:var(--gold);color:var(--ink);padding:22px;margin-bottom:25px}.finish h2{font:30px Burrow,serif;margin:0 0 10px}.finish p{margin:0 0 10px}.finish button{width:auto}.details{margin-top:35px;border-top:1px solid #68816c;padding-top:20px;display:grid;grid-template-columns:1fr 1fr;gap:35px}.details h2{font:24px Burrow,serif;margin:0 0 10px}.details p{font-size:15px;color:#ecdfc5;max-width:65ch}footer{font-size:14px;color:#ecdfc5;margin-top:30px;padding-bottom:10px}noscript{display:block;padding:20px;background:var(--cream);color:var(--ink)}
@media(max-width:760px){header{padding:14px 20px}.masthead{display:block;margin:10px 0 22px}.masthead p{max-width:450px;margin-top:12px}main{padding:0 20px 30px}.work{grid-template-columns:1fr;gap:25px}.request{position:static;transform:none;padding:20px}.request h2{margin:10px 0;font-size:25px}.clue{min-height:0;font-size:18px}.request p{margin:8px 0}.signed{display:none}.count{padding-bottom:8px}#feedback{min-height:0}.request .primary{width:auto;margin-right:12px}.board{gap:12px}.label{font-size:15px;padding-left:2px}.tags{font-size:11px;padding-left:2px}.details{grid-template-columns:1fr;gap:14px}.bookmark{padding:5px 5px 9px}.masthead h1{max-width:500px}.caption{margin-bottom:0}}
@media(max-width:380px){.board{grid-template-columns:repeat(2,minmax(0,1fr))}header span{display:none}}
@media(prefers-reduced-motion:reduce){.bookmark{transition:none}.bookmark:hover,.bookmark[aria-pressed=true]{transform:none}}
</style>
</head>
<body>
<header><a href="index.php">Back to Chloe Reads Jon</a><span>A little lost-and-found for good ideas</span></header>
<main>
<div class="masthead"><h1>Bookmark Burrow</h1><p>Nine saved discoveries. Six rather vague requests. Can you find the bookmark they meant?</p></div>
<noscript>This game needs JavaScript. You can still read the inspiration link at the bottom.</noscript>
<section id="finish" class="finish" hidden tabindex="-1" aria-labelledby="finishTitle"><h2 id="finishTitle">Every good idea, found again.</h2><p id="result"></p><p>Pictures give memory a shortcut. Tags help when the picture is not enough. A title called “that nice thing” helps absolutely nobody.</p><button class="primary" id="replay">Play again</button></section>
<div class="work">
<section class="request" aria-labelledby="requestTitle">
<div class="count"><span id="roundLabel">Request 1 of 6</span><span id="found">0 found</span></div>
<h2 id="requestTitle" tabindex="-1">A note from Owl</h2>
<p id="clue" class="clue"></p><p class="signed" id="signature"></p>
<p id="selection">Choose a picture bookmark.</p>
<button class="primary" id="file" disabled>That’s the one</button><button class="primary" id="next" hidden>Next request</button>
<p id="feedback" role="status" aria-live="polite"></p>
<button class="plain" id="hint">Give me a clue</button><p id="hintText" hidden></p>
</section>
<section class="archive" aria-labelledby="archiveTitle">
<div class="toolbar"><h2 id="archiveTitle">The saved collection</h2><button class="switch" id="pictures" aria-pressed="false">Hide pictures</button></div>
<label class="search"><span>Search titles or tags</span><input id="search" type="search" placeholder="Try: night, water, music…" autocomplete="off"></label>
<div class="board" id="board"></div><p id="empty" role="status" hidden>No bookmarks match. Try a shorter word or clear the search.</p>
<p class="caption" id="visibleCount">9 illustrated bookmarks. All discoveries in this game are fictional.</p>
</section>
</div>
<div class="details"><section><h2>How to rummage</h2><p>Read the request, choose a bookmark, then press “That’s the one”. Search can narrow the collection. There is no timer and wrong guesses cost nothing. Try hiding the pictures for a different kind of hunt.</p></section>
<section><h2>A picture worth saving</h2><p>In his 2024 post, Jon liked that Notion could give each bookmark a picture. This little game lets that idea do the work. Inspired by Jon’s <a href="?source=1">Pinboard vs Notion</a>.</p></section></div>
<footer>Made for Jon and Nathan. Original illustrated bookmarks, a slightly disorganized woodland, and no accounts required.</footer>
</main>
<script>
'use strict';
const items=[
['Moon on loan','night · science · sky','a brass telescope and crescent moon'],
['The little red one','wheels · play · vintage','a red vintage toy car'],
['One more chapter','home · reading · warm','tea beside an open book'],
['The long way home','water · walking · stone','a mossy stone bridge over a creek'],
['Somewhere worth going','walking · travel · paper','a fox holding a folded map'],
['Something to hum','music · wood · strings','a violin and bow'],
['Under the ferns','nature · red · forest','a red mushroom beneath ferns'],
['Out past the harbour','water · travel · wind','a small blue sailboat'],
['After the sun goes','night · forest · light','a paper lantern in a cedar tree']
];
const requests=[
{who:'Owl',text:'“I saved something for looking at the moon. It was brass, if that helps. I gave it a very unhelpful title.”',target:0,hint:'Look for the telescope. Its tags include science.',note:'A picture gets you from “brass thing” to telescope without needing the exact title.'},
{who:'Badger',text:'“It crosses water, but it never sails. Moss on the top. A lovely place for a slow walk.”',target:3,hint:'Water and walking belong together on this bookmark.',note:'Water narrows the search, but walking separates the bridge from the boat.'},
{who:'Hare',text:'“Four wheels. Red paint. Small enough to park in my pocket. Not sensible transport, admittedly.”',target:1,hint:'Try the tag vintage.',note:'A tiny red car is much easier to recognize than “The little red one”.'},
{who:'Fox',text:'“The forest one for after sunset. It glows, but you cannot use it to look at the moon.”',target:8,hint:'Search forest. Which result also has the tag night?',note:'Two tags can distinguish a lantern from a mushroom or a telescope.'},
{who:'Mouse',text:'“Something made of wood that sings. Strings, not pages. I bookmarked it for our next concert.”',target:5,hint:'Try searching music or strings.',note:'Useful tags describe what you will remember, not just what a page is called.'},
{who:'Otter',text:'“A trip on water. The wind does the hard work. Definitely not the mossy crossing Badger wanted.”',target:7,hint:'Water and wind will lead you to the sailboat.',note:'The best bookmark is the one you can find again. Otter would also like a snack.'}
];
const $=id=>document.getElementById(id);
let round=0,selected=null,solved=false,mistakes=0,hints=0;
items.forEach((item,i)=>{
 const b=document.createElement('button');b.className='bookmark';b.id='bookmark-'+i;b.type='button';b.setAttribute('aria-pressed','false');
 const pic=document.createElement('span');pic.className='picture';pic.style.setProperty('--x',((i%3)*50)+'%');pic.style.setProperty('--y',(Math.floor(i/3)*50)+'%');pic.setAttribute('role','img');pic.setAttribute('aria-label',item[2]);
 const name=document.createElement('span');name.className='label';name.textContent=item[0];
 const tags=document.createElement('span');tags.className='tags';tags.textContent=item[1];
 b.append(pic,name,tags);b.addEventListener('click',()=>choose(i));$('board').append(b);
});
function choose(i){
 if(solved)return;
 selected=i;
 items.forEach((_,n)=>$('bookmark-'+n).setAttribute('aria-pressed',String(n===i)));
 $('selection').textContent='Selected: '+items[i][0]+'.';$('file').disabled=false;$('feedback').textContent='';
}
function search(){
 const q=$('search').value.trim().toLowerCase();
 let count=0;items.forEach((item,i)=>{const match=(item[0]+' '+item[1]).toLowerCase().includes(q);$('bookmark-'+i).hidden=!match;if(match)count++});
 $('empty').hidden=count!==0;$('visibleCount').textContent=count+' of 9 bookmarks shown. Fictional discoveries, genuine rummaging.';
 if(selected!==null&&$('bookmark-'+selected).hidden){$('bookmark-'+selected).setAttribute('aria-pressed','false');selected=null;$('file').disabled=true;$('selection').textContent='Choose a picture bookmark.'}
}
function load(focus){
 selected=null;solved=false;$('search').value='';search();
 items.forEach((_,i)=>{$('bookmark-'+i).setAttribute('aria-pressed','false');$('bookmark-'+i).disabled=false});
 const r=requests[round];$('roundLabel').textContent='Request '+(round+1)+' of 6';$('found').textContent=round+' found';
 $('requestTitle').textContent='A note from '+r.who;$('clue').textContent=r.text;$('signature').textContent='With thanks, '+r.who;
 $('selection').textContent='Choose a picture bookmark.';$('file').disabled=true;$('file').hidden=false;$('next').hidden=true;
 $('feedback').textContent='';$('hintText').hidden=true;$('hint').hidden=false;$('hint').disabled=false;$('hintText').textContent=r.hint;
 if(focus)$('requestTitle').focus();
}
$('search').addEventListener('input',search);
$('file').addEventListener('click',()=>{
 if(selected===null||solved)return;
 if(selected!==requests[round].target){mistakes++;$('feedback').textContent='Not quite. '+items[selected][0]+' does not fit every detail. Try another bookmark.';return}
 solved=true;$('feedback').textContent='Found it! '+requests[round].note;$('found').textContent=(round+1)+' found';
 $('next').textContent=round===5?'Open the thank-you note':'Next request';$('next').hidden=false;$('next').focus();$('file').hidden=true;$('hint').hidden=true;
 items.forEach((_,i)=>$('bookmark-'+i).disabled=true);
});
$('hint').addEventListener('click',()=>{hints++;$('hintText').hidden=false;$('hint').textContent='Clue shown';$('hint').disabled=true;$('requestTitle').focus()});
$('next').addEventListener('click',()=>{
 if(round<5){round++;$('hint').textContent='Give me a clue';load(true)}
 else{$('finish').hidden=false;$('result').textContent='You reunited all six neighbours with their bookmarks, using '+hints+' clue'+(hints===1?'':'s')+' and '+mistakes+' extra guess'+(mistakes===1?'':'es')+'. The burrow is most grateful.';
 $('finish').focus();$('finish').scrollIntoView({block:'start',behavior:'instant'});$('next').hidden=true;}
});
$('pictures').addEventListener('click',()=>{
 const hide=!$('board').classList.contains('text-only');$('board').classList.toggle('text-only',hide);
 $('pictures').setAttribute('aria-pressed',String(hide));$('pictures').textContent=hide?'Show pictures':'Hide pictures';
 document.querySelectorAll('.picture').forEach(p=>p.setAttribute('aria-hidden',String(hide)));
});
$('replay').addEventListener('click',()=>{
 round=0;mistakes=0;hints=0;$('finish').hidden=true;$('hint').textContent='Give me a clue';load(true);
});
load(false);
</script>
</body></html>
